"Santuário": {circulo:"1º Círculo", escola:"Abjuração", classes:["Clérigo", "Psiônico"], concentracao:false, ritual:false, tempo:"Ação Bônus", alcance:"9 metros", componentes:"V, S, M (o caco de um espelho)", duracao:"1 minuto", efeito:"Protege 1 criatura à distância: quem mirar nela com ataque/magia de dano precisa passar em Salv. Sabedoria ou escolher outro alvo/perder a ação (não protege contra área de efeito). Encerra se o protegido atacar/conjurar/causar dano.", escalonamento:"—", pagina:"330"},
"Saraivada de Espinhos": {circulo:"1º Círculo", escola:"Invocação", classes:["Guardião"], concentracao:false, ritual:false, tempo:"Ação Bônus, que você realiza imediatamente após atingir uma criatura com um ataque com arma à Distância", alcance:"Pessoal", componentes:"V", duracao:"Instantânea", efeito:"Após acertar com arma à distância: espinhos explodem — alvo + tudo num raio de 1,5m: Salv. Destreza ou 1d10 dano Perfurante (sucesso=metade).", escalonamento:"Upcast: +1d10.", pagina:"331"},
"Servo Invisível": {circulo:"1º Círculo", escola:"Invocação", classes:["Bardo", "Bruxo", "Mago"], concentracao:false, ritual:true, tempo:"Ação ou Ritual", alcance:"18 metros", componentes:"V, S, M (um pedaço de barbante e de madeira)", duracao:"1 hora", efeito:"Cria uma força invisível (CA10, 1 PV, Força 2) que faz tarefas simples por comando mental (buscar, limpar, consertar, servir) — move 4,5m por Ação Bônus. Não ataca. Encerra a mais de 18m de você ou se reduzida a 0 PV.", escalonamento:"—", pagina:"331"},
"Sifão Vital": {circulo:"1º Círculo", escola:"Evocação", classes:["Psiônico"], concentracao:false, ritual:false, tempo:"Ação", alcance:"36 metros", componentes:"S", duracao:"Instantânea", efeito:"Orbe de energia psiônica alimentado pela sua força vital. Ataque mágico à distância: 1d10 dano Psíquico; você pode gastar 1 Dado de Vida pra +1d10 de dano.", escalonamento:"Upcast: +1d10 de dano, e +1 Dado de Vida utilizável por círculo acima do 1º.", pagina:"UA-20"},
"Sono": {circulo:"1º Círculo", escola:"Encantamento", classes:["Bardo", "Feiticeiro", "Mago", "Psiônico"], concentracao:true, ritual:false, tempo:"Ação", alcance:"18 metros", componentes:"V, S, M (uma pitada de areia ou pétalas de rosa)", duracao:"Concentração, até 1 minuto", efeito:"Área (esfera 1,5m): Salv. Sabedoria ou Incapacitado até o fim do próximo turno (repete a salvaguarda; falhar de novo = Inconsciente pela duração). Dano ou sacudir alguém encerra o efeito nele. Quem não dorme (elfos, imunes a Exaustão) passa automaticamente.", escalonamento:"—", pagina:"333"},
"Sussurros Dissonantes": {circulo:"1º Círculo", escola:"Encantamento", classes:["Bardo", "Psiônico"], concentracao:false, ritual:false, tempo:"Ação", alcance:"18 metros", componentes:"V", duracao:"Instantânea", efeito:"Melodia dissonante na mente do alvo. Salv. Sabedoria ou 3d6 dano Psíquico + usa a Reação pra fugir de você pela rota mais segura (sucesso=metade do dano, sem fuga forçada).", escalonamento:"Upcast: +1d6.", pagina:"334"},
"Vitalidade Vazia": {circulo:"1º Círculo", escola:"Necromancia", classes:["Feiticeiro", "Mago"], concentracao:false, ritual:false, tempo:"Ação", alcance:"Pessoal", componentes:"V, S, M (uma gota de álcool)", duracao:"Instantânea", efeito:"Ganha 2d4+4 PV temporários.", escalonamento:"Upcast: +5 PV temp por círculo.", pagina:"342"},
"Acalmar Emoções": {circulo:"2º Círculo", escola:"Encantamento", classes:["Bardo", "Clérigo", "Psiônico"], concentracao:true, ritual:false, tempo:"Ação", alcance:"18 metros", componentes:"V, S", duracao:"Concentração, até 1 minuto", efeito:"Onda calmante nos corações ao redor. Cada Humanoide numa esfera de 6m: Salv. Carisma ou (escolha 1 por criatura): imune a Amedrontado/Enfeitiçado pela duração (suprime se já afetado); ou fica Indiferente a inimigos à escolha (encerra se sofrer dano ou ver aliado sofrendo dano).", escalonamento:"—", pagina:"239"},
"Alterar-se": {circulo:"2º Círculo", escola:"Transmutação", classes:["Feiticeiro", "Mago"], concentracao:true, ritual:false, tempo:"Ação", alcance:"Pessoal", componentes:"V, S", duracao:"Concentração, até 1 hora", efeito:"Você molda seu próprio corpo. Escolha 1 (pode trocar com Ação de Usar Magia): Adaptação Aquática (guelras, respira debaixo d'água, Deslocamento de Natação = Deslocamento); Armas Naturais (garras/presas/chifres/cascos — Ataque Desarmado vira 1d6 do tipo, usa atributo de conjuração); Mudar Aparência (altura/peso/rosto/voz/espécie, sem mudar tamanho/estatística).", escalonamento:"—", pagina:"240"},
"Aprimorar Atributo": {circulo:"2º Círculo", escola:"Transmutação", classes:["Bardo", "Clérigo", "Druida", "Feiticeiro", "Guardião", "Mago", "Psiônico"], concentracao:true, ritual:false, tempo:"Ação", alcance:"Toque", componentes:"V, S, M (pelo ou uma pena)", duracao:"Concentração, até 1 hora", efeito:"Toca; escolhe 1 atributo — Vantagem em testes desse atributo, pela duração (1h).", escalonamento:"Upcast: +1 alvo/círculo (atributo pode variar por alvo).", pagina:"242"},
"Arma Espiritual": {circulo:"2º Círculo", escola:"Evocação", classes:["Clérigo"], concentracao:true, ritual:false, tempo:"Ação Bônus", alcance:"18 metros", componentes:"V, S", duracao:"Concentração, até 1 minuto", efeito:"Cria uma arma espectral flutuante à escolha. Ataque corpo a corpo imediato: 1d8 + mod. de conjuração dano Energético. Ação Bônus em turnos seguintes: move 6m + repete o ataque.", escalonamento:"Upcast: +1d8.", pagina:"243"},
"Arma Mágica": {circulo:"2º Círculo", escola:"Transmutação", classes:["Feiticeiro", "Guardião", "Mago", "Paladino"], concentracao:false, ritual:false, tempo:"Ação Bônus", alcance:"Toque", componentes:"V, S", duracao:"1 hora", efeito:"Toca arma não-mágica: vira +1 no ataque/dano pela duração (1h). Encerra se reconjurar.", escalonamento:"Upcast: +2 com espaço 3º-5º círculo; +3 com 6º+.", pagina:"243"},
"Arrombar": {circulo:"2º Círculo", escola:"Transmutação", classes:["Bardo", "Feiticeiro", "Mago", "Psiônico"], concentracao:false, ritual:false, tempo:"Ação", alcance:"18 metros", componentes:"V", duracao:"Instantânea", efeito:"Destranca/desemperra 1 fechadura mundana à vista (só 1 se houver várias); suprime Tranca Arcana por 10 min. Gera estrondo audível a 90m.", escalonamento:"—", pagina:"244"},
"Augúrio": {circulo:"2º Círculo", escola:"Adivinhação", classes:["Clérigo", "Druida", "Mago"], concentracao:false, ritual:true, tempo:"1 minuto ou Ritual", alcance:"Pessoal", componentes:"V, S, M (varetas, ossos, cartas ou símbolos semelhantes especialmente marcados no valor de 25 ou mais PO)", duracao:"Instantânea", efeito:"Pede um presságio sobre um curso de ação nos próximos 30 min: Prosperidade (bom), Infortúnio (mau), Ambos, ou Nada — mestre decide. Não considera fatores que podem mudar o resultado depois. Repetir antes de Descanso Longo: 25% cumulativo de não receber resposta a cada vez.", escalonamento:"—", pagina:"245"},
