"Corda Extradimensional": {circulo:"2º Círculo", escola:"Transmutação", classes:["Mago"], concentracao:false, ritual:false, tempo:"Ação", alcance:"Toque", componentes:"V, S, M (um pedaço de corda)", duracao:"1 hora", efeito:"Toca corda: ela paira até ficar reta, abre portal 1x1,5m no topo pra um bolso extradimensional (cabe 8 criaturas Médias-). Nada atravessa exceto pelo portal; tudo cai quando a magia acaba (1h).", escalonamento:"—", pagina:"263"},
