"Coroa da Loucura": {circulo:"2º Círculo", escola:"Encantamento", classes:["Bardo", "Bruxo", "Feiticeiro", "Mago", "Psiônico"], concentracao:true, ritual:false, tempo:"Ação", alcance:"36 metros", componentes:"V, S", duracao:"Concentração, até 1 minuto", efeito:"Salv. Sabedoria (Humanoide) ou Enfeitiçado — deve atacar corpo a corpo a criatura que você escolhe mentalmente antes de se mover (age normal se não houver alvo). Repete salvaguarda no fim do turno dele. Você precisa manter Ação de Usar Magia nos seus turnos ou encerra.", escalonamento:"—", pagina:"264"},
