"Esquentar Metal": {circulo:"2º Círculo", escola:"Transmutação", classes:["Bardo", "Druida", "Psiônico"], concentracao:true, ritual:false, tempo:"Ação", alcance:"18 metros", componentes:"V, S, M (um pedaço de ferro e uma chama)", duracao:"Concentração, até 1 minuto", efeito:"Objeto de metal fica em brasa: 2d8 Ígneo a quem tocar (no cast, e de novo por Ação Bônus em turnos seguintes). Quem segura/veste e sofre dano: Salv. Constituição ou solta o item (senão Desvantagem em ataque/testes até seu próximo turno).", escalonamento:"Upcast: +1d8.", pagina:"280"},
"Flecha Ácida de Melf": {circulo:"2º Círculo", escola:"Evocação", classes:["Mago"], concentracao:false, ritual:false, tempo:"Ação", alcance:"27 metros", componentes:"V, S, M (folha de ruibarbo em pó)", duracao:"Instantânea", efeito:"Ataque à distância: 4d4 Ácido + 2d4 Ácido no fim do próximo turno do alvo (erro=só metade do dano inicial).", escalonamento:"Upcast: +1d4 em ambos.", pagina:"282"},
